module.exports=[1162,a=>{"use strict";[74,69,66,80,72,71,75].reduce((a,b)=>a+b,0);[64,69,55,43,68,73,78,69].reduce((a,b)=>a+b,0);let b="antinorm",c="Antinorm";[{productName:"Set to Protect SPF 50 PA++++ Sunscreen Mist",slug:"set-to-protect-sunscreen",brand:c,brandSlug:b,priceRange:"Rs.799-Rs.1,199",productType:"sunscreen",category:"Sunscreens",subCategory:"Hybrid Sunscreen",concern:"UV protection, primer, setting spray, pollution shield, daily photoprotection",summary:"Antinorm's flagship product is a multi-function SPF 50 PA++++ setting spray built around a seven-filter UV system, one of the most advanced photostable filter combinations available in the Indian market. The system includes Tinosorb S (Bemotrizinol), Tinosorb M, Mexoryl SX, DHHB (Uvinul A+), Uvinul T150, Ensulizole, and Benzophenone-4. Critically, there is no Oxybenzone, no Octinoxate, and no Avobenzone, avoiding all three of the most contested organic UV filters. Denatured Alcohol appears near the top of the list as a required solvent for the setting spray format; the brand explicitly acknowledges this trade-off in their product description. Supporting actives include Niacinamide, Ectoin, Panthenol, Glycerin, Green Tea, and Centella Asiatica. No published SPF test report is publicly available.",score:76,scoreLabel:"Good",publicDecisionLabel:"Mostly credible with gaps",image:"https://antinorm.co/cdn/shop/files/Image1.jpg?v=1778203583",pillars:[{name:"Public INCI Safety Screen",score:25,max:30,note:"This formula deliberately avoids the three most contested UV filters: no Oxybenzone (Benzophenone-3, classified as a Category 1 Endocrine Disruptor by ECHA in 2025), no Octinoxate (under FDA and EU hormonal disruption review), and no Avobenzone (which degrades in sunlight without careful co-formulation). No mandatory deductions apply. Discretionary: Denatured Alcohol appears at a high concentration in this leave-on sunscreen and can disrupt the stratum corneum lipid layer with chronic daily use, particularly on dry or compromised skin (-4). Benzophenone-4 (Sulisobenzone) is structurally distinct from Oxybenzone and EU-permitted at up to 5% in leave-on; some studies note mild hormonal activity at high doses (-1). No fragrance allergens, no parabens, and all UV filters comply with EU and India regulations."},{name:"Formula Logic Inference",score:23,max:25,note:"The seven-filter UV system is among the most advanced sunscreen chemistry available to Indian consumers at any price. Tinosorb S (Bemotrizinol) is a broad-spectrum UVA and UVB filter that is intrinsically photostable via reverse photoisomerism. Tinosorb M is a hybrid organic-inorganic filter that photostabilises co-formulated filters. Mexoryl SX provides high photostability UVA coverage. DHHB (Uvinul A+) covers UVA1 and UVA2. Uvinul T150 is one of the most photostable UVB filters available. Ensulizole covers UVB. Together they provide comprehensive, degradation-resistant broad-spectrum coverage. Ectoin is a stress-protectant helping repair UV-induced cellular stress. Pullulan film-forming provides the setting spray lock. Minor deduction: Denatured Alcohol as a key solvent is a necessary trade-off for the spray format but creates a formulation logic tension for a daily leave-on product."},{name:"Public Claim Support",score:17,max:25,note:"The SPF 50 PA++++ and seven next-generation UV filter claims are fully verifiable from the published ingredient list. Every filter is identifiable by name. The brand publicly acknowledges the Denatured Alcohol trade-off, which is an unusual and positive standard for the Indian market. Gaps: no independent SPF test report has been published to confirm the stated protection factor. Benzophenone-4's regulatory profile is not communicated to consumers. The blue light protection claim is not strongly supported by current evidence and is a marketing claim."},{name:"Test Result Transparency",score:7,max:15,evidenceGrade:"C",note:"No published SPF test report. For a sunscreen making an SPF 50 PA++++ claim, the absence of a public test certificate is a significant transparency gap. The seven-filter system is advanced but unverified by any published independent test. Grade C reflects a lack of published study despite the product being a regulated SPF claim product."},{name:"Consumer Clarity",score:4,max:5,note:"The brand communicates the Denatured Alcohol trade-off directly on the product page, which is notably transparent for the Indian market. Full ingredient list is published. Gaps: no SPF test certificate published; Benzophenone-4 concern profile not disclosed."}],keyActives:[{name:"Tinosorb S (Bemotrizinol)",function:"Broad-spectrum UVA/UVB, highest photostability via reverse photoisomerism; self-stabilising"},{name:"Tinosorb M",function:"Broad-spectrum hybrid organic-inorganic filter; photostabilises co-filters"},{name:"Mexoryl SX (Terephthalylidene Dicamphor Sulfonic Acid)",function:"High photostability UVA filter; exceptional UVA protection"},{name:"DHHB (Uvinul A+)",function:"UVA1/UVA2 filter with outstanding safety and photostability profile"},{name:"Uvinul T150 (Ethylhexyl Triazone)",function:"Highly photostable UVB filter"},{name:"Ectoin",function:"Stress-protectant from salt-loving bacteria; helps repair UV-induced cellular stress"},{name:"Niacinamide",function:"Anti-inflammatory, anti-PIH; inhibits UV-triggered melanosome transfer"}],ingredients:[{name:"Aqua",note:"Solvent base",flag:"ok"},{name:"Denatured Alcohol",note:"High-list position indicates meaningful concentration. Required as solvent for hydrophilic UV filters and setting spray texture. Brand explicitly acknowledges this trade-off. Chronic daily leave-on use can disrupt the skin outer lipid layer at high concentrations.",flag:"warn"},{name:"Phenylbenzimidazole Sulfonic Acid",note:"Ensulizole; water-soluble UVB filter with excellent safety profile",flag:"ok"},{name:"Terephthalylidene Dicamphor Sulfonic Acid",note:"Mexoryl SX; highly photostable UVA filter. Approved in EU, Australia, and India",flag:"ok"},{name:"Benzophenone 4",note:"Sulisobenzone; UVA/UVB broad-spectrum filter. Different from Benzophenone-3 (Oxybenzone). EU permitted at 5% leave-on. Lower hormonal concern profile than BP-3 but mild activity at high doses noted in some studies",flag:"info"},{name:"Niacinamide",note:"Anti-inflammatory, inhibits UV-triggered melanosome transfer for PIH prevention, barrier support",flag:"ok"},{name:"Phenoxyethanol (and) Ethylhexylglycerin",note:"Preservative blend; Phenoxyethanol within EU/India 1% limit",flag:"info"},{name:"Methylene Bis-Benzotriazolyl Tetramethylbutylphenol",note:"Tinosorb M; broad-spectrum hybrid filter, photostabilises co-formulated UV filters",flag:"ok"},{name:"Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine",note:"Tinosorb S (Bemotrizinol); broad-spectrum, self-stabilising. One of the most photostable organic UV filters available",flag:"ok"},{name:"Diethylamino Hydroxybenzoyl Hexyl Benzoate",note:"DHHB (Uvinul A+); UVA1/UVA2 with excellent photostability and safety profile",flag:"ok"},{name:"Ethylhexyl Triazone",note:"Uvinul T150; highly photostable UVB filter, excellent safety profile",flag:"ok"},{name:"Sodium Hydroxide",note:"pH adjuster (trace)",flag:"ok"},{name:"D-Panthenol",note:"Pro-vitamin B5; barrier restoration and hydration, partially offsets alcohol-related dryness",flag:"ok"},{name:"Glycerin",note:"Humectant; moisture retention to mitigate alcohol-induced dryness",flag:"ok"},{name:"Green Tea Extract",note:"Antioxidants; anti-inflammatory and post-UV protection",flag:"ok"},{name:"Centella Asiatica Extract",note:"Barrier support and anti-inflammatory",flag:"ok"},{name:"Ectoin",note:"Stress-protectant amino acid derivative from salt-loving bacteria; helps repair UV-induced cellular stress",flag:"ok"},{name:"Pullulan",note:"Polysaccharide film-former; provides the setting spray lock effect and forms invisible protective veil",flag:"ok"},{name:"Polyvinylpyrrolidone",note:"Film-forming polymer; supports setting spray functionality",flag:"ok"},{name:"Sodium Gluconate",note:"Chelating agent; supports preservative efficacy",flag:"ok"},{name:"Disodium EDTA",note:"Chelating agent; formula stability",flag:"ok"}],globalScreen:{eu_1223_2009:"All UV filters comply with EU Regulation 1223/2009 Annex VI. No Oxybenzone (BP-3), no Octinoxate. Benzophenone-4 is EU permitted at up to 5% in leave-on. No prohibited substances.",india_cr_2020:"Compliant with India Cosmetics Regulation 2020. All UV filters are Schedule S permitted.",health_canada_hotlist:"No hotlist substances detected. Denatured Alcohol and UV filters are not on the Canadian hotlist.",canada_nhpid:"Not applicable. No Natural Health Product claims.",tga_australia:"UV filters comply with Australian sunscreen regulations. No restricted substances.",us_fda_21cfr:"Tinosorb S and Tinosorb M are not FDA-approved OTC sunscreen ingredients for the US market. Product is marketed in India, not the US.",korea_mfds:"No restricted substances under Korean MFDS cosmetics regulations.",aicis_australia:"No restricted industrial chemicals.",echa_svhc:"No SVHC detected. No Oxybenzone present; ECHA 2025 Annex XIV candidate classification for Oxybenzone is therefore not triggered.",iarc:"No IARC classified carcinogens in formula."},inciCompleteness:{status:"Full INCI on brand PDP",flags:[]},claimsCheck:[{claim:"SPF 50 PA++++",evidenceStatus:"Mentioned only",decision:"Needs proof",note:"SPF claim is plausible from the seven-filter system but no independent published test report is publicly available to confirm the stated protection factor."},{claim:"Seven next-generation UV filters, photostable",evidenceStatus:"Evidence visible",decision:"Publicly supported",note:"All seven filters are identifiable by INCI name and their photostability is established in published literature."},{claim:"Blue light protection",evidenceStatus:"Mentioned only",decision:"Needs proof",note:"Blue light protection from cosmetic SPF products is not well-supported by current evidence and is generally considered a marketing claim."}],missingProof:["Independent published SPF test report confirming SPF 50 PA++++ protection factor","Consumer communication on Benzophenone-4 regulatory profile"],cleanSheetNote:"The seven-filter photostable system is genuinely one of India's most advanced sunscreen formulations. The brand's honest disclosure of the Denatured Alcohol trade-off sets a positive transparency standard. The main gap for this scoring band is the absence of a published SPF test report, which is a meaningful omission for a product making an SPF 50 PA++++ claim.",pass_badges:["INCI Verified","Paraben-Free","No Oxybenzone","No Octinoxate","Photostable 7-Filter System","SPF 50 PA++++","Reef-Safe Filters"],warn_badges:["Denatured Alcohol (Barrier Disruption Risk, Leave-on)","No SPF Test Report Published"],info_badges:["Tinosorb S + M","Mexoryl SX","Ectoin Stress Protection","Primer + Setting Spray"],indiaContext:"The seven-filter photostable system makes this one of the most rigorously formulated sunscreens available in the Indian market at any price. For India's UV Index 8-11+ year-round environment, avoiding avobenzone photodegradation and Oxybenzone's endocrine disruptor classification are meaningful advantages. The setting spray format is particularly relevant for Indian climates where heavy sunscreen textures cause sweating and pilling under makeup. Ectoin's stress-protection is valuable under India's chronic high-UV load. The Denatured Alcohol trade-off is most relevant for individuals with dry or compromised-barrier skin; for oily skin types prevalent in India's humid regions, the alcohol may actually be beneficial for texture and sebum control. Reapply every 2-3 hours outdoors.",analyzedAt:"2026-06-10",skinTypeTags:["oily","normal","combination"],concernTags:["Photoageing","Tanning","PIH"],suitabilityTags:["Daily Use","Humid Weather","Makeup Wearers"],cautionTags:["Drying Alcohol","SPF Not Verified"],fragranceStatus:"free",alcoholStatus:"contains-drying",routineSlot:"AM"},{productName:"Shower in Seconds",slug:"shower-in-seconds",brand:c,brandSlug:b,priceRange:"Rs.899",productType:"rinse-off",category:"Face Cleansers",subCategory:"Gel Cleanser",concern:"Quick cleansing, barrier-gentle cleansing, on-the-go freshness",summary:"A rinse-off cleanser with a premium mild surfactant system: Cocamidopropyl Betaine (amphoteric), Decyl Glucoside and Caprylyl/Capryl Glucoside (sugar-derived non-ionic, very mild), and Sodium Cocoyl Glutamate (amino acid-based anionic, the gentlest anionic surfactant class). Niacinamide in a rinse-off cleanser is supported by recent studies showing meaningful delivery even with brief contact. Lactic Acid provides mild exfoliation. Colloidal Oatmeal adds barrier protection. Three labelling compliance issues are noted: (1) 'Geogard ECT' is a Lonza trade name and must list constituent ingredients individually (Benzyl Alcohol, Salicylic Acid, Glycerin, Sorbic Acid); this hides Benzyl Alcohol, a declared EU fragrance allergen, from consumers. (2) 'Colloidal Oatmeal' is not an approved cosmetic INCI name. (3) Individual fatty acids are listed separately rather than as a named source oil.",score:72,scoreLabel:"Good",publicDecisionLabel:"Mostly credible with gaps",image:"https://antinorm.co/cdn/shop/files/81.png?v=1773822972",pillars:[{name:"Public INCI Safety Screen",score:26,max:30,note:"No SLS, no SLES, no synthetic Parfum. The surfactant system (Sodium Cocoyl Glutamate, Decyl Glucoside, Caprylyl/Capryl Glucoside, Cocamidopropyl Betaine) represents the gentlest available anionic and non-ionic surfactant classes. No mandatory deductions apply for this rinse-off product. The preservative listed as 'Geogard ECT' contains Benzyl Alcohol, a declared EU fragrance allergen. In a rinse-off product, brief contact substantially reduces sensitisation risk, but the allergen is invisible to consumers reading the trade name. Discretionary deduction: -2 for Benzyl Alcohol allergen not visible from label, -1 for overall labelling non-compliance indicating reduced formula verification confidence, -1 for Lactic Acid mild exfoliant in a cleanser context for sensitive users."},{name:"Formula Logic Inference",score:21,max:25,note:"The surfactant system is state-of-the-art for gentle cleansing. Sodium Cocoyl Glutamate has pH compatibility with skin that makes it significantly less disruptive to the acid mantle than sulphate-based alternatives. Inulin is a prebiotic that feeds beneficial bacteria on skin, supporting the microbiome after washing. Saccharomyces Ferment delivers ferment-derived antioxidants. Kakadu Plum provides natural Vitamin C and polyphenol antioxidants. Sodium Hyaluronate adds surface hydration. The three labelling compliance gaps (Geogard ECT trade name, Colloidal Oatmeal non-standard name, individual fatty acids not attributed to a source oil) mean the full formula cannot be independently verified."},{name:"Public Claim Support",score:16,max:25,note:"The SLS-free and mild surfactant claims are verifiable from the INCI list. The niacinamide rinse-off efficacy claim is technically supported by recent independent studies. The major transparency gap: three labelling compliance issues mean consumers cannot fully verify the formula. Geogard ECT hides Benzyl Alcohol from allergen-sensitive consumers. The source oil behind individually listed fatty acids cannot be identified. No independent gentleness test report is published. These gaps collectively reduce public claim reliability."},{name:"Test Result Transparency",score:6,max:15,evidenceGrade:"C",note:"No published efficacy, gentleness, or safety test report for this cleanser. The surfactant system is well-characterised in published literature, but the brand has not published any product-level study. Grade C reflects no published product-specific evidence."},{name:"Consumer Clarity",score:3,max:5,note:"Full ingredient list is published on antinorm.co. However, three labelling compliance issues create notable consumer clarity gaps: Geogard ECT hides Benzyl Alcohol from allergen readers, Colloidal Oatmeal is a non-compliant name, and five fatty acids listed individually make the source material unidentifiable."}],keyActives:[{name:"Sodium Cocoyl Glutamate",function:"Amino acid-based anionic surfactant; the gentlest anionic surfactant class for facial cleansing"},{name:"Decyl Glucoside + Caprylyl/Capryl Glucoside",function:"Sugar-derived non-ionic surfactants; very mild, low sensitisation risk"},{name:"Niacinamide",function:"Anti-inflammatory and sebum-regulating; effective even in rinse-off contact window"},{name:"Colloidal Oatmeal",function:"Skin protectant; anti-itch, barrier support, soothing"},{name:"Inulin",function:"Prebiotic; feeds beneficial bacteria to support post-cleanse microbiome balance"},{name:"Kakadu Plum Extract",function:"Natural Vitamin C; antioxidant polyphenols"}],ingredients:[{name:"Aqua (Water)",note:"Solvent base",flag:"ok"},{name:"Cocamidopropyl Betaine",note:"Amphoteric surfactant; mild, compatible with other surfactant classes, foam booster",flag:"ok"},{name:"Decyl Glucoside",note:"Sugar-derived non-ionic surfactant; very mild, low sensitisation, biodegradable",flag:"ok"},{name:"Caprylyl/Capryl Glucoside",note:"Sugar glucoside surfactant; mild non-ionic, eco-friendly, skin-compatible",flag:"ok"},{name:"Sodium Cocoyl Glutamate",note:"Glutamic acid-derived anionic surfactant; the mildest anionic surfactant class. pH-compatible with skin, minimal barrier disruption",flag:"ok"},{name:"Aloe Barbadensis Leaf Juice",note:"Soothing and anti-inflammatory base",flag:"ok"},{name:"Niacinamide",note:"Anti-inflammatory, sebum-regulating. Evidence supports meaningful delivery even in rinse-off cleansers at adequate contact time",flag:"ok"},{name:"Chamomilla Recutita (Matricaria) Flower Extract",note:"Chamomile; anti-inflammatory and skin-soothing",flag:"ok"},{name:"Inulin",note:"Plant-derived prebiotic; supports skin microbiome post-cleansing by feeding beneficial bacteria",flag:"ok"},{name:"Lactic Acid",note:"Mild exfoliant; at late position, low concentration appropriate for rinse-off gentle exfoliation and pH buffering",flag:"ok"},{name:"Linoleic Acid",note:"Omega-6 fatty acid; barrier-supportive. Listed individually rather than as a named oil; non-standard labelling practice",flag:"info"},{name:"Linolenic Acid",note:"Omega-3 fatty acid; anti-inflammatory and barrier-supportive. Individual listing non-standard",flag:"info"},{name:"Oleic Acid",note:"Monounsaturated fatty acid emollient. Individual listing non-standard",flag:"info"},{name:"Palmitic Acid",note:"Saturated fatty acid; emollient and emulsifier. Individual listing non-standard",flag:"info"},{name:"Stearic Acid",note:"Saturated fatty acid emollient/emulsifier. Individual listing non-standard. Source oil unidentifiable from label",flag:"info"},{name:"Tocopherol",note:"Natural Vitamin E; antioxidant protecting formula and skin lipids",flag:"ok"},{name:"Panthenol",note:"Pro-vitamin B5; barrier repair and skin conditioning",flag:"ok"},{name:"Glycerin",note:"Humectant; moisture retention post-cleanse",flag:"ok"},{name:"Polyglyceryl-10 Laurate",note:"Natural-derived non-ionic emulsifier/surfactant; very mild and biodegradable",flag:"ok"},{name:"Sodium Hyaluronate",note:"HA salt; provides post-cleanse surface hydration",flag:"ok"},{name:"Saccharomyces Ferment",note:"Yeast ferment filtrate; skin-brightening and conditioning ferment-derived actives",flag:"ok"},{name:"Geogard ECT",note:"Lonza commercial trade name for a blend: Benzyl Alcohol (EU fragrance allergen), Salicylic Acid, Glycerin, Sorbic Acid. Listing by trade name is not fully INCI compliant; Benzyl Alcohol allergen not visible to consumers reading the ingredient list",flag:"warn"},{name:"Propanediol",note:"Plant-derived humectant and solvent",flag:"ok"},{name:"Colloidal Oatmeal",note:"Non-compliant INCI name (correct: 'Avena Sativa (Oat) Kernel Flour' or 'Beta-Glucan'). Well-evidenced skin protectant and anti-itch. Naming non-compliance",flag:"warn"},{name:"Zea Mays (Corn) Starch",note:"Absorbent starch; texture modifier",flag:"ok"},{name:"Sucrose Stearate",note:"Sugar-derived ester emulsifier; mild and skin-compatible",flag:"ok"},{name:"Sodium Phytate",note:"Chelating agent; formula stability",flag:"ok"},{name:"Citric Acid",note:"pH adjustment; maintains acidic pH compatible with skin microbiome and formula stability",flag:"ok"}],globalScreen:{eu_1223_2009:"No prohibited substances. Benzyl Alcohol (in Geogard ECT) is an EU declared allergen and should be listed individually per EU Regulation 1223/2009. Listing by trade name creates a compliance gap.",india_cr_2020:"No Schedule S prohibited substances. Preservative system is permitted under India Cosmetics Regulation 2020.",health_canada_hotlist:"No hotlist substances detected.",canada_nhpid:"Not applicable. No Natural Health Product claims.",tga_australia:"No restricted or prohibited substances per TGA cosmetic standards.",us_fda_21cfr:"All ingredients comply with 21 CFR cosmetic ingredient use requirements.",korea_mfds:"No restricted substances under Korean MFDS cosmetics regulations.",aicis_australia:"No restricted industrial chemicals.",echa_svhc:"No SVHC detected in formula.",iarc:"No IARC classified carcinogens in formula."},inciCompleteness:{status:"Full INCI on brand PDP",flags:["Geogard ECT listed by trade name, not constituent INCI names; Benzyl Alcohol allergen not visible","Colloidal Oatmeal is not a compliant INCI name","Five fatty acids listed individually without naming source oil"]},claimsCheck:[{claim:"SLS-free, gentle surfactant system",evidenceStatus:"Evidence visible",decision:"Publicly supported",note:"Surfactant system (glutamate, glucosides, betaine) is verifiably mild from the INCI list. No SLS or SLES."},{claim:"Niacinamide efficacy in rinse-off",evidenceStatus:"Evidence visible",decision:"Publicly supported",note:"Recent independent studies support meaningful niacinamide delivery in brief-contact rinse-off cleansers at adequate concentrations."},{claim:"Prebiotic microbiome benefit (Inulin)",evidenceStatus:"Mentioned only",decision:"Needs proof",note:"Inulin's prebiotic mechanism is established in research but brand has not published any product-specific microbiome study."}],missingProof:["Published gentleness or irritation study for this specific cleanser","Geogard ECT trade name must be replaced with individual INCI names for compliance","Colloidal Oatmeal must be renamed to compliant INCI nomenclature"],cleanSheetNote:"Genuinely one of India's best-formulated cleansers from a surfactant selection standpoint. The labelling compliance issues (Geogard ECT trade name hiding Benzyl Alcohol, Colloidal Oatmeal non-INCI name) are solvable quality control corrections that would materially improve the consumer clarity score.",pass_badges:["INCI Verified","Paraben-Free","SLS-Free","SLES-Free","Amino Acid Surfactant","Microbiome-Gentle"],warn_badges:["Geogard ECT (Trade Name Non-Compliant: hides Benzyl Alcohol allergen)","Non-Standard Name: Colloidal Oatmeal"],info_badges:["Prebiotic (Inulin)","Kakadu Plum","Fatty Acids Listed Individually"],indiaContext:"The amino acid surfactant base (Sodium Cocoyl Glutamate) is optimal for Indian skin that experiences barrier disruption from hard water, over-cleansing during monsoon sweating, and alkaline bar soaps common across price points. Hard water in Delhi NCR, Bengaluru, and Rajasthan significantly raises the pH of SLS-based cleansers; glutamate-based surfactants are more pH-resilient. Inulin's prebiotic benefit is relevant in India where urban pollution and antibacterial products commonly disrupt the skin microbiome. The Colloidal Oatmeal and Chamomile combination makes this particularly suitable for sensitive skin types that flare during seasonal transitions.",analyzedAt:"2026-06-10",skinTypeTags:["sensitive","normal","combination"],concernTags:["Sensitive Skin","Barrier Damage","Microbiome Support"],suitabilityTags:["Daily Use","Beginner Friendly","Sensitive Skin","Fragrance Sensitive Users"],cautionTags:[],fragranceStatus:"free",alcoholStatus:"free"},{productName:"Facial in a Flash",slug:"facial-in-a-flash",brand:c,brandSlug:b,priceRange:"Rs.1,199",productType:"treatment",category:"Serums",subCategory:"Pigmentation Serum",concern:"Brightening, hyperpigmentation, exfoliation, anti-dullness",summary:"A botanically dense multi-active face treatment with a comprehensive brightening active stack: Carica Papaya Fruit Extract at high concentration (papain enzyme for proteolytic exfoliation), Niacinamide, Lactic Acid (AHA), Kojic Acid, and Arbutin, targeting melanin pathways from multiple angles. Multiple anti-inflammatory botanicals support post-exfoliation recovery (Centella Asiatica, Licorice Root, Skullcap, Eclipta Prostrata). Three formulation concerns: (1) Citrus Aurantium Amara (Neroli) Flower Oil is a fragrance essential oil containing linalool, limonene, and geraniol in a leave-on treatment. (2) Rosa Damascena Flower Extract contains four major fragrance allergens. (3) Both allergen sources are combined in a product whose exfoliation mechanism transiently increases skin permeability. Chlorphenesin is present as a preservative with post-market contact reaction associations.",score:63,scoreLabel:"Fair",publicDecisionLabel:"Needs proof",image:"https://antinorm.co/cdn/shop/files/26.png?v=1768287023",pillars:[{name:"Public INCI Safety Screen",score:23,max:30,note:"Two botanical fragrance sources with significant allergen loads are present in a leave-on treatment. Citrus Aurantium Amara (Bitter Orange/Neroli) Flower Oil contains linalool, linalyl acetate, limonene, and geraniol, all major EU declared fragrance allergens. Rosa Damascena Flower Extract contains geraniol, citronellol, farnesol, and linalool, four additional major allergens. The concern is compounded by the product's own mechanism: exfoliation from Papain, Lactic Acid, and Quartz transiently increases skin permeability, amplifying allergen absorption. A -5 deduction applies for essential oil allergen load in a leave-on treatment (equivalent to the Parfum in leave-on rule). Chlorphenesin is a permitted preservative but has post-market surveillance reports of contact reactions; -2 discretionary. No synthetic Parfum, no parabens, no MIT."},{name:"Formula Logic Inference",score:19,max:25,note:"The brightening active stack targets melanin formation from five distinct pathways. Papain enzyme provides proteolytic exfoliation by cleaving peptide bonds in dead skin protein. Lactic Acid provides chemical exfoliation. Kojic Acid blocks the copper at the active site of the melanin-producing enzyme. Arbutin inhibits the same enzyme via a gentler competitive substrate mechanism. Licorice Root's Glabridin adds melanin-blocking and anti-inflammatory action. Niacinamide inhibits melanosome transfer to surrounding skin cells. This five-pathway approach is comprehensively designed. Critical counterproductive element: including fragrance allergen sources (Neroli oil, Rosa Damascena) in an exfoliation product that transiently opens the barrier is poor formulation logic that offsets the advanced brightening design."},{name:"Public Claim Support",score:13,max:25,note:"The brightening active claims (Kojic Acid, Arbutin, Papain, Niacinamide, Lactic Acid) are technically supportable from the INCI list. However, no concentrations are disclosed for Kojic Acid, Arbutin, or Papain, the three actives where dose determines whether the product will actually work. Bitter Orange Flower Oil's fragrance allergen content is not communicated to consumers anywhere in the product description. Chlorphenesin's contact reaction association is not disclosed. 'Rose Extract' at an earlier list position uses a non-standard name, obscuring potential additional allergen contribution. No published efficacy study for this treatment."},{name:"Test Result Transparency",score:6,max:15,evidenceGrade:"C",note:"No published clinical test, efficacy study, or safety report for this product. The five-pathway brightening mechanism is scientifically credible but no brand-published data substantiates results. Grade C reflects no published product-specific evidence."},{name:"Consumer Clarity",score:2,max:5,note:"Multiple safety concerns are not communicated to consumers: fragrance allergens from Neroli oil and Rosa Damascena in a post-exfoliation leave-on context, the Chlorphenesin contact reaction risk, the 'Rose Extract' non-standard naming, and the absence of concentration disclosures for actives where dose is critical."}],keyActives:[{name:"Carica Papaya (Papaya) Fruit Extract",function:"Papain enzyme at high concentration; proteolytic exfoliation dissolves dead skin protein bridges without physical abrasion"},{name:"Niacinamide",function:"Inhibits melanosome transfer; anti-inflammatory; supports barrier post-exfoliation"},{name:"Lactic Acid",function:"AHA exfoliation; stimulates cell turnover"},{name:"Kojic Acid",function:"Blocks the copper at the active site of the melanin-producing enzyme; inhibits melanin synthesis"},{name:"Arbutin",function:"Gentle inhibitor of the melanin-producing enzyme; alternative to hydroquinone"},{name:"Glycyrrhiza Uralensis (Licorice) Root Extract",function:"Glabridin: melanin-blocking and anti-inflammatory"},{name:"Centella Asiatica Extract",function:"Barrier repair post-exfoliation; wound-healing compounds"}],ingredients:[{name:"Carica Papaya (Papaya) Fruit Extract",note:"Highest concentration. Papain enzyme provides proteolytic exfoliation by cleaving peptide bonds in dead skin protein. Gentle enzymatic alternative to physical or acid exfoliation",flag:"ok"},{name:"Niacinamide",note:"High-list position confirms meaningful dose. Melanosome transfer inhibitor and anti-inflammatory",flag:"ok"},{name:"Aloe Barbadensis Leaf Extract",note:"Soothing anti-inflammatory; supports recovery from enzymatic exfoliation",flag:"ok"},{name:"Fragaria Ananassa (Strawberry) Fruit Extract",note:"Antioxidants; mild brightening support",flag:"ok"},{name:"Prunus Serotina (Wild Cherry) Fruit Extract",note:"Antioxidants",flag:"ok"},{name:"Rose Extract",note:"Non-standard ingredient name (should be 'Rosa Damascena Flower Extract' or similar). Contains fragrance allergens. Disclosure gap.",flag:"warn"},{name:"Fragaria Chiloensis (Strawberry) Fruit Extract",note:"Duplicate strawberry entry with different species name from Fragaria Ananassa. Redundant or separate extract variety.",flag:"info"},{name:"Melia Azadirachta Leaf Extract",note:"Neem leaf; anti-bacterial, anti-fungal, anti-inflammatory",flag:"ok"},{name:"Centella Asiatica Extract",note:"Barrier repair and wound healing post-exfoliation",flag:"ok"},{name:"Rosa Damascena Flower Extract",note:"Anti-inflammatory polyphenols but contains fragrance allergens: geraniol, citronellol, farnesol, linalool. Leave-on allergen concern applies, particularly in a post-exfoliation product.",flag:"warn"},{name:"Panthenol",note:"Pro-vitamin B5; barrier restoration",flag:"ok"},{name:"Glycyrrhiza Uralensis (Licorice) Root Extract",note:"Glabridin: melanin-blocking and anti-inflammatory; works alongside Kojic Acid and Arbutin",flag:"ok"},{name:"Moringa Oleifera Seed Oil",note:"Anti-inflammatory oil; antioxidant",flag:"ok"},{name:"Citrus Aurantium Amara (Bitter Orange) Flower Oil",note:"Neroli oil, fragrance essential oil. Contains linalool, linalyl acetate, geraniol, limonene, all major EU fragrance allergens in a leave-on treatment. Counterproductive formulation choice for a post-exfoliation product with transiently increased permeability.",flag:"warn"},{name:"Scutellaria Baicalensis Root Extract",note:"Skullcap; baicalin and wogonin flavonoids, potent antioxidant and anti-inflammatory",flag:"ok"},{name:"Eclipta Prostrata Extract",note:"Bhringraj; traditional UV-protective and anti-inflammatory herb",flag:"ok"},{name:"Butyrospermum Parkii (Shea) Butter",note:"Rich occlusive emollient; barrier sealing post-treatment",flag:"ok"},{name:"Lactic Acid",note:"Exfoliant; meaningful concentration for chemical exfoliation at this list position",flag:"ok"},{name:"Kojic Acid",note:"Melanin enzyme inhibitor; EU permitted at 1% in leave-on",flag:"ok"},{name:"Arbutin",note:"Gentle melanin enzyme inhibitor; well-tolerated, gentler than hydroquinone",flag:"ok"},{name:"Betaine",note:"Natural humectant from sugar beet; osmolyte function",flag:"ok"},{name:"Citric Acid",note:"pH adjustment; maintains acidic environment for exfoliant efficacy",flag:"ok"},{name:"Quartz",note:"Silica particles for mild physical exfoliation texture; rounded cosmetic-grade particles",flag:"ok"},{name:"Propylene Glycol",note:"Humectant and solvent; at late position, concentration likely minimal",flag:"info"},{name:"Dipropylene Glycol",note:"Humectant and fragrance solvent",flag:"ok"},{name:"Caprylic/Capric Triglyceride",note:"MCT emollient; non-comedogenic, lightweight",flag:"ok"},{name:"Cetearyl Alcohol",note:"Fatty alcohol emulsifier/emollient",flag:"ok"},{name:"Stearic Acid",note:"Fatty acid emulsifier/thickener",flag:"ok"},{name:"Cellulose",note:"Natural polymer thickener/texture modifier",flag:"ok"},{name:"Carbomer",note:"Synthetic polymer gel-former",flag:"ok"},{name:"Polyglyceryl-3 Methylglucose Distearate",note:"Natural-derived non-ionic emulsifier",flag:"ok"},{name:"Glyceryl Stearate",note:"Co-emulsifier and emollient",flag:"ok"},{name:"Triethanolamine",note:"pH adjuster; trace quantity at late position. Standard use.",flag:"info"},{name:"Sodium Gluconate",note:"Chelating agent",flag:"ok"},{name:"Magnesium Aluminum Silicate",note:"Mineral thickener/stabiliser",flag:"ok"},{name:"Chlorphenesin",note:"Preservative permitted in leave-on products. Associated with contact reactions in post-market surveillance reports. Less preferred for sensitive skin. Risk not disclosed on product page.",flag:"warn"},{name:"Xanthan Gum",note:"Ferment-derived biopolymer thickener",flag:"ok"},{name:"Phenoxyethanol",note:"Preservative; within EU/India 1% limit",flag:"info"},{name:"Triethylene Glycol",note:"Humectant and solvent; skin-compatible at cosmetic concentrations",flag:"ok"},{name:"1,2-Hexanediol",note:"Mild preservative booster and humectant",flag:"ok"},{name:"Titanium Dioxide",note:"White pigment for product opacity/colour",flag:"ok"},{name:"Trisodium Ethylenediamine Disuccinate",note:"Biodegradable chelating agent; eco-preferable alternative to EDTA",flag:"ok"}],globalScreen:{eu_1223_2009:"Kojic Acid is EU-regulated in leave-on products at 1% (Regulation 2023/1490). Neroli Oil and Rosa Damascena contain declared EU fragrance allergens (linalool, limonene, geraniol, citronellol, farnesol) that must be individually listed on the label above 0.001% in leave-on products. No prohibited substances.",india_cr_2020:"No Schedule S prohibited substances. Kojic Acid is permitted in India. Fragrance allergen labelling requirements differ from EU; individual allergen listing is not currently mandatory in India.",health_canada_hotlist:"No hotlist substances detected.",canada_nhpid:"Not applicable. No Natural Health Product claims.",tga_australia:"No restricted or prohibited substances per TGA cosmetic standards.",us_fda_21cfr:"All ingredients comply with 21 CFR cosmetic ingredient use requirements.",korea_mfds:"Kojic Acid is regulated in Korea; concentration limits apply. No other restricted substances.",aicis_australia:"No restricted industrial chemicals.",echa_svhc:"No SVHC detected in formula.",iarc:"No IARC classified carcinogens in formula."},inciCompleteness:{status:"Full INCI on brand PDP",flags:["Neroli Oil and Rosa Damascena contain EU declared fragrance allergens; these are not individually named on the label","Rose Extract at earlier position uses non-standard name","No concentration disclosures for key actives (Kojic Acid, Arbutin, Papain)"]},claimsCheck:[{claim:"Multi-pathway brightening and PIH treatment",evidenceStatus:"Evidence visible",decision:"Publicly supported",note:"Kojic Acid, Arbutin, Lactic Acid, Niacinamide, and Papain are all present and their individual mechanisms are well-evidenced in literature. However, no concentrations disclosed."},{claim:"Enzymatic exfoliation via Papain",evidenceStatus:"Evidence visible",decision:"Publicly supported",note:"Carica Papaya Fruit Extract at high list concentration supports the Papain exfoliation mechanism."},{claim:"Fragrance-free or allergen-safe for sensitive skin",evidenceStatus:"Missing",decision:"Not publicly supported",note:"Neroli Oil and Rosa Damascena both contain major EU fragrance allergens. The product is not safe for fragrance-sensitive users. This is not communicated on the product page."}],missingProof:["Concentration disclosures for Kojic Acid, Arbutin, and Papain where dose determines efficacy","Published efficacy study for PIH treatment","Fragrance allergen labelling for Neroli Oil and Rosa Damascena components"],cleanSheetNote:"The five-pathway brightening stack is one of the most sophisticated in the Indian market under Rs.1500. The scoring gap is the fragrance essential oil inclusion (Neroli, Rosa Damascena) in an exfoliation leave-on, which is a direct formulation logic contradiction: introducing allergens to skin whose permeability has been transiently increased by the product's own mechanism.",pass_badges:["INCI Verified","Paraben-Free","Multi-Mechanism Brightening","Enzymatic + AHA Exfoliation"],warn_badges:["Neroli Oil (Fragrance Allergens, Leave-on)","Rosa Damascena (Fragrance Allergens, Leave-on)","Rose Extract (Non-Standard Name)","Chlorphenesin (Contact Reaction Risk)"],info_badges:["Papain Enzyme","Kojic + Arbutin + Niacinamide","5-Pathway Depigmentation"],indiaContext:"Papain enzyme exfoliation resonates with Indian consumers familiar with raw papaya face pack traditions. The five-pathway brightening approach is the most comprehensive available without prescription actives. Particularly relevant for darker Fitzpatrick skin types where PIH from acne, friction, and hormonal changes is chronic and often undertreated. The essential oil allergen concern is significant: post-exfoliation skin is transiently more permeable and reactive, making fragrance allergen application particularly ill-timed.",analyzedAt:"2026-06-10",skinTypeTags:["normal","combination","oily"],concernTags:["Pigmentation","Dullness","Tanning","Texture","Skin Renewal"],suitabilityTags:["Melanin Rich Skin","Active Experienced Users"],cautionTags:["Contains Fragrance","Fragrance Allergen Flag","Essential Oil Flag","High Irritation Potential"],fragranceStatus:"essential-oil",routineSlot:"PM"},{productName:"Bye Bye Blow Dry",slug:"bye-bye-blow-dry",brand:c,brandSlug:b,priceRange:"Rs.999-Rs.1,199",productType:"leave-on",category:"Hair Care",subCategory:"Leave In Conditioner",concern:"Frizz control, heat protection, hair conditioning, air-dry styling",summary:"A hair leave-in treatment designed to eliminate the blow-dry step. Built on a cationic conditioning base (Cetrimonium Chloride) with amino-functional silicone (Amodimethicone) for heat protection and frizz control. Hydrolyzed Pea Protein films around the hair shaft for structural support. Seaweed extracts (Hypnea Musciformis, Gelidiella Acerosa) provide marine polysaccharide conditioning. Mango Seed Butter, Avocado Oil, Castor Oil, and Sunflower Seed Oil provide fatty acid emolliency. Three labelling errors are noted: (1) Sunflower Seed Oil (Helianthus Annuus) is listed twice, a clear duplicate; (2) 'Hydrolyzed Vegetable Protein' does not specify the source protein as required for allergen identification; (3) 'Centrimonium Chloride' and 'Cetrimonium Chloride' are the same ingredient listed under different spellings. Also flagged: Cyclopentasiloxane (D5) is an environmentally persistent silicone restricted in rinse-off products in the EU.",score:66,scoreLabel:"Fair",publicDecisionLabel:"Needs proof",image:"https://antinorm.co/cdn/shop/files/15_1.png?v=1768286871",pillars:[{name:"Public INCI Safety Screen",score:24,max:30,note:"No mandatory deductions apply. No fragrance, no parabens, no MIT, no synthetic Parfum. Propylene Glycol appears near the top of the list (high concentration) in a leave-on scalp product; it is a penetration enhancer that can increase absorption of co-formulated actives through the scalp, which has higher blood vessel density than facial skin (-3 discretionary). Cyclopentasiloxane (D5) is an environmentally persistent silicone; EU has restricted it above 0.1% in rinse-off cosmetics, though the leave-on restriction is not yet in force; precautionary environmental concern (-2). Three labelling errors reduce formula verification confidence (-1 collective deduction for compliance gap)."},{name:"Formula Logic Inference",score:20,max:25,note:"Core conditioning chemistry is well-chosen. Cetrimonium Chloride is the standard cationic conditioner that adsorbs to the negatively charged surface of damaged hair to smooth the cuticle. Amodimethicone is an amino-modified silicone that selectively deposits on damaged hair shaft sites, providing heat protection and frizz control. Biotinoyl Tripeptide-1 has evidence for hair follicle stimulation. Polyquaternium-7 adds detangling and film-forming benefit. Marine algae extracts contribute polysaccharide conditioning. The oil blend of Mango Seed Butter, Avocado, Castor, and Sunflower provides good emolliency. Three labelling errors mean the formula cannot be fully independently verified."},{name:"Public Claim Support",score:14,max:25,note:"Three labelling errors undermine transparency for a brand positioned on scientific credibility. First: 'Hydrolyzed Vegetable Protein' does not identify the source protein; this is required because wheat and soy proteins are common allergens, and consumers cannot assess their risk from this label. Second: Sunflower Seed Oil (Helianthus Annuus) appears twice, suggesting the ingredient list was not verified. Third: 'Centrimonium Chloride' and 'Cetrimonium Chloride' are the same ingredient under different spellings. For heat protection and frizz control claims, no independent test report has been published."},{name:"Test Result Transparency",score:6,max:15,evidenceGrade:"C",note:"No published performance study, heat protection test, or safety data for this product. The conditioning chemistry is credible from literature, but the brand has not published product-specific evidence. Grade C reflects no published product-level data."},{name:"Consumer Clarity",score:2,max:5,note:"Three labelling errors create notable consumer clarity gaps: source protein in Hydrolyzed Vegetable Protein is unidentifiable (allergen blind spot), duplicate Sunflower Seed Oil entry confuses the ingredient list, and the Centrimonium/Cetrimonium spelling discrepancy creates ambiguity. D5 environmental concern and Propylene Glycol penetration enhancer properties are not disclosed."}],keyActives:[{name:"Cetrimonium Chloride",function:"Cationic conditioner; adsorbs to negatively charged damaged hair cuticle, reducing friction and static"},{name:"Amodimethicone",function:"Amino-modified silicone; selective deposition at damaged hair sites, heat protection, intense frizz control"},{name:"Hydrolyzed Pea Protein",function:"Protein hydrolysate that penetrates and fills structural hair damage, increasing tensile strength"},{name:"Biotinoyl Tripeptide-1",function:"Biotin-peptide with evidence for hair follicle stimulation and hair density support"},{name:"Marine Algae Extracts (Hypnea Musciformis + Gelidiella Acerosa)",function:"Marine polysaccharide conditioning; moisture retention and hair surface protection"}],ingredients:[{name:"Aqua",note:"Solvent base",flag:"ok"},{name:"Propylene Glycol",note:"Humectant/solvent at high-list position (high concentration). Penetration enhancer in leave-on scalp applications; increases penetration of co-actives.",flag:"warn"},{name:"Hamamelis Virginiana (Witch Hazel) Extract",note:"Astringent tannins; frizz reduction via keratin tightening effect",flag:"ok"},{name:"Glycerin",note:"Humectant; moisture retention for hair shaft",flag:"ok"},{name:"Centrimonium Chloride",note:"Alternate spelling of Cetrimonium Chloride. Cationic conditioner. Also listed as 'Cetrimonium Chloride' at a later position; duplicate entry with different spelling.",flag:"warn"},{name:"Trideceth-12",note:"Non-ionic ethoxylated emulsifier/surfactant for formula stability",flag:"ok"},{name:"Isoamyl Laurate",note:"Lightweight ester emollient; improves hair feel and spreadability",flag:"ok"},{name:"Aloe Barbadensis Leaf (Aloevera) Juice",note:"Soothing and moisturising base for scalp contact",flag:"ok"},{name:"Sodium PCA",note:"Natural humectant; moisture retention for hair and scalp",flag:"ok"},{name:"Caprylyl Glycol",note:"Mild preservative booster and humectant",flag:"ok"},{name:"Xylitylglucoside (And) Anhydroxylitol (And) Xylitol",note:"Moisture retention complex for hair shaft surface",flag:"ok"},{name:"Hydrolyzed Pea Protein",note:"Protein hydrolysate films around damaged hair shaft; fills structural gaps and increases tensile strength",flag:"ok"},{name:"Hypnea Musciformis (Algae) Extract",note:"Red algae marine polysaccharide; hair conditioning and moisture retention",flag:"ok"},{name:"PEG-40 Hydrogenated Castor Oil",note:"Non-ionic emulsifier/solubiliser",flag:"ok"},{name:"Chamomilla Recutita (Matricaria) Flower Extract",note:"Chamomile; anti-inflammatory for scalp",flag:"ok"},{name:"Helianthus Annuus (Sunflower) Seed Oil",note:"Linoleic acid-dominant emollient oil for hair shaft conditioning",flag:"ok"},{name:"Mangifera Indica (Mango) Seed Butter",note:"Emollient butter; stearic and oleic acid for hair shaft lubrication and shine",flag:"ok"},{name:"Persea Gratissima (Avocado) Oil",note:"Oleic and linoleic acid emollient; penetrating oil for hair shaft",flag:"ok"},{name:"Ricinus Communis (Castor) Seed Oil",note:"Ricinoleic acid; increases hair shaft viscosity and provides gloss",flag:"ok"},{name:"Coco-Glucoside",note:"Sugar-derived non-ionic surfactant/emulsifier; mild",flag:"ok"},{name:"Gelidiella Acerosa Extract",note:"Red algae polysaccharide extract; marine conditioning and moisture retention",flag:"ok"},{name:"Hydrolyzed Vegetable Protein",note:"Non-compliant ingredient name; source protein must be specified (e.g., 'Hydrolyzed Wheat Protein'). Cannot assess allergen risk without source identification.",flag:"warn"},{name:"Acrylates/C10-30 Alkyl Acrylate Crosspolymer",note:"Polymer thickener for formula texture",flag:"ok"},{name:"Triethanolamine",note:"pH adjuster; trace quantity for formula pH calibration",flag:"ok"},{name:"Hydroxyethylcellulose",note:"Natural-derived polymer thickener",flag:"ok"},{name:"Cyclopentasiloxane And Dimethiconol",note:"Volatile silicone D5 + non-volatile silicone. D5 (Cyclopentasiloxane) is environmentally persistent; restricted in rinse-off products in EU. Leave-on restriction not yet in force but flagged as a precautionary environmental concern.",flag:"warn"},{name:"Polyquaternium-7",note:"Cationic polymer; detangling, anti-static, film-forming on hair",flag:"ok"},{name:"Sorbitol",note:"Polyol humectant",flag:"ok"},{name:"Helianthus Annuus (Sunflower) Seed Oil",note:"DUPLICATE: same ingredient already listed above. Labelling error.",flag:"warn"},{name:"Glycine Soja (Soybean) Oil",note:"Linoleic and linolenic acid emollient; lightweight conditioning oil",flag:"ok"},{name:"Panthenol",note:"Pro-vitamin B5; scalp and hair shaft conditioning",flag:"ok"},{name:"Polysorbate 20",note:"Non-ionic surfactant/emulsifier",flag:"ok"},{name:"Biotinoyl Tripeptide-1",note:"Biotin-peptide; evidence for hair follicle stimulation and hair density",flag:"ok"},{name:"Sodium Benzoate",note:"Preservative effective below pH 4.2; paired with Potassium Sorbate for dual system",flag:"ok"},{name:"Potassium Sorbate",note:"Preservative; combined with Sodium Benzoate for broad-spectrum preservation",flag:"ok"},{name:"Sodium Gluconate",note:"Chelating agent",flag:"ok"},{name:"Allantoin",note:"Soothing, skin/scalp conditioning",flag:"ok"},{name:"Amodimethicone",note:"Amino-modified silicone; selectively deposits on damaged hair sites, provides heat protection and frizz control",flag:"ok"},{name:"Cetrimonium Chloride",note:"Same ingredient as 'Centrimonium Chloride' listed earlier. Duplicate entry with different spelling. Labelling error.",flag:"warn"}],globalScreen:{eu_1223_2009:"Cyclopentasiloxane (D5) is restricted above 0.1% in rinse-off cosmetics per EU Regulation 2018/1516; leave-on restriction not yet in force. No prohibited substances.",india_cr_2020:"No Schedule S prohibited substances. Preservative system (Sodium Benzoate + Potassium Sorbate) is permitted.",health_canada_hotlist:"No hotlist substances detected.",canada_nhpid:"Not applicable. No Natural Health Product claims.",tga_australia:"No restricted or prohibited substances per TGA cosmetic standards.",us_fda_21cfr:"All ingredients comply with 21 CFR cosmetic ingredient use requirements.",korea_mfds:"No restricted substances under Korean MFDS cosmetics regulations.",aicis_australia:"No restricted industrial chemicals.",echa_svhc:"No SVHC detected in formula.",iarc:"No IARC classified carcinogens in formula."},inciCompleteness:{status:"Full INCI on brand PDP",flags:["Hydrolyzed Vegetable Protein: source protein not specified (allergen gap)","Helianthus Annuus Seed Oil listed twice (duplicate)","Centrimonium Chloride and Cetrimonium Chloride are the same ingredient listed under two different spellings"]},claimsCheck:[{claim:"Frizz control and air-dry styling",evidenceStatus:"Evidence visible",decision:"Publicly supported",note:"Cetrimonium Chloride and Amodimethicone are the established frizz-control chemistry. Claims are credible from INCI."},{claim:"Heat protection",evidenceStatus:"Mentioned only",decision:"Needs proof",note:"Amodimethicone provides known heat protection properties but no published test report for this product confirms the protection level."},{claim:"Labelling accuracy",evidenceStatus:"Missing",decision:"Not publicly supported",note:"Three labelling errors (duplicate ingredient, spelling variant, non-compliant protein name) mean the ingredient list does not meet INCI compliance standards."}],missingProof:["Published heat protection test for this product","Source protein specification for Hydrolyzed Vegetable Protein","Correction of three labelling errors"],cleanSheetNote:"The core conditioning chemistry (Cetrimonium + Amodimethicone + Biotinoyl Tripeptide-1) is genuinely well-designed. The three labelling errors are a quality control gap that contradicts the brand's scientific credibility positioning and are solvable corrections.",pass_badges:["INCI Verified","Paraben-Free","Fragrance-Free","SLS-Free"],warn_badges:["3 Labelling Errors","Propylene Glycol (Penetration Enhancer, Leave-on Scalp)","Cyclopentasiloxane D5 (Environmental)","Hydrolyzed Vegetable Protein (Allergen Source Unspecified)"],info_badges:["Biotinoyl Tripeptide-1","Amodimethicone Heat Protection","Marine Algae Conditioning"],indiaContext:"Air-drying hair is the norm for Indian consumers who wash hair frequently due to heat and sweat. A leave-in that eliminates blow-drying time is well-positioned for the Indian market. The Cetrimonium plus Amodimethicone combination is the most effective chemistry for frizz control in India's humidity, particularly during monsoon season. The Castor Oil inclusion resonates with Indian hair care traditions. The labelling errors are concerning for a brand positioning on scientific credibility.",analyzedAt:"2026-06-10",concernTags:["Frizz","Heat Damage","Hair Strength"],suitabilityTags:["Daily Use","Monsoon Hair"],cautionTags:[],fragranceStatus:"free",alcoholStatus:"free"},{productName:"Hair & Everywhere",slug:"hair-and-everywhere",brand:c,brandSlug:b,priceRange:"Rs.1,899",productType:"leave-on",category:"Hair Care",subCategory:"Hair Oil",concern:"Hair hydration, body mist, multi-use fragrance and moisturisation",summary:"A multi-use leave-on mist marketed for both hair and body. Lightweight water-glycerin-aloe base with witch hazel astringency. Niacinamide and Allantoin provide skin-conditioning benefit. Coconut Water adds mineral electrolytes. The significant concern: four fragrance essential oils at meaningful concentrations in a daily full-body leave-on product. Lavandula Angustifolia (Lavender) Oil contains linalool and linalyl acetate. Santalum Album (Sandalwood) Oil contains farnesol and is a known contact sensitiser. Rosa Damascena (Rose) Flower Oil contains geraniol, citronellol, farnesol, and linalool. Citrus Aurantium Dulcis (Orange) Peel Oil contains limonene and linalool and may carry phototoxic compounds. Total fragrance allergen load from four oils applied to the full body daily is a meaningful sensitisation risk. Sandalwood is classified as Vulnerable on the IUCN Red List.",score:57,scoreLabel:"Fair",publicDecisionLabel:"Needs proof",image:"https://antinorm.co/cdn/shop/files/55_1.png?v=1771927623",pillars:[{name:"Public INCI Safety Screen",score:22,max:30,note:"Four fragrance essential oils are present at meaningful concentrations in a daily full-body leave-on product. This represents the equivalent of Parfum in leave-on: -5 for essential oil allergen load in a leave-on product. The individual fragrance allergens from these oils (linalool, linalyl acetate, geraniol, citronellol, farnesol, limonene) are not individually named on the label; they are present above threshold in the oils but consumers cannot verify them from the ingredient list as written: -3 for undisclosed EU Annex III allergens. Total mandatory-equivalent deduction: -8. No synthetic Parfum, no parabens, no MIT. Polysorbate-20 minor formatting note (should be 'Polysorbate 20'). Orange Peel Oil may contain phototoxic compounds with morning full-body application."},{name:"Formula Logic Inference",score:16,max:25,note:"The base formula is simple and well-executed: water, Glycerin, and Aloe Vera Juice provide a lightweight humectant foundation. Witch Hazel adds astringency that helps seal hair cuticles and provides a skin-tightening effect. Niacinamide provides anti-inflammatory and barrier-supportive benefit. Sodium PCA is a natural moisturising factor component. Coconut Water contributes potassium, magnesium, and amino acids. However, the four fragrance essential oils are the primary differentiator and they are the primary formulation concern: the allergen load from four oils for daily full-body use is a significant formulation logic gap. The premium pricing reflects the botanical oils selected, which are precisely the elements creating the safety concern."},{name:"Public Claim Support",score:12,max:25,note:"Full ingredient list is published with correct botanical nomenclature for the four essential oils. The transparency gap: none of the four fragrance oils are identified as allergen sources anywhere in the product description or marketing. The phototoxic risk from Orange Peel Oil with outdoor application is not disclosed. Sandalwood's IUCN Vulnerable status is not disclosed. No published efficacy study for any claim. The 'multi-use hair and body' benefit is plausible from the formulation but the allergen risk of full-body daily leave-on application is the dominant consumer information gap."},{name:"Test Result Transparency",score:5,max:15,evidenceGrade:"D",note:"No published safety, patch test, or efficacy study for this product. For a product with four fragrance allergen sources in a daily full-body leave-on, the absence of any published safety data is a notable gap. Grade D reflects no evidence and a heightened safety concern from the allergen profile."},{name:"Consumer Clarity",score:2,max:5,note:"Four fragrance allergen sources are not communicated as such to consumers. The phototoxic risk from Orange Peel Oil before outdoor exposure is not disclosed. Sandalwood's IUCN Vulnerable sourcing concern is not communicated. Consumers cannot assess their allergen risk from the product page."}],keyActives:[{name:"Lavandula Angustifolia (Lavender) Oil",function:"Fragrance; mild anti-inflammatory. Contains linalool and linalyl acetate, both EU declared fragrance allergens."},{name:"Santalum Album (Sandalwood) Oil",function:"Fragrance; sesquiterpene alcohols. Known contact sensitiser. Contains farnesol (EU declared allergen). IUCN Vulnerable species."},{name:"Rosa Damascena (Rose) Flower Oil",function:"Fragrance; contains geraniol, citronellol, farnesol, linalool, four major EU fragrance allergens."},{name:"Citrus Aurantium Dulcis (Orange) Peel Oil",function:"Fragrance; contains limonene and linalool (EU allergens). May carry phototoxic compounds; full-body application before UV exposure is a concern."},{name:"Niacinamide",function:"Anti-inflammatory and barrier support for skin application"}],ingredients:[{name:"Aqua",note:"Solvent base",flag:"ok"},{name:"Glycerin",note:"Humectant; moisture retention for hair and skin",flag:"ok"},{name:"Aloe Barbadensis (Aloe Vera) Leaf Juice",note:"Soothing and anti-inflammatory base",flag:"ok"},{name:"Hamamelis Virginiana (Witch Hazel) Leaf Extract",note:"Astringent; mild frizz-sealing for hair and pore-tightening on skin",flag:"ok"},{name:"Lavandula Angustifolia (Lavender) Oil",note:"Fragrance essential oil at meaningful concentration. Contains linalool and linalyl acetate, EU declared fragrance allergens in a leave-on full-body product.",flag:"warn"},{name:"Polysorbate-20",note:"Non-ionic emulsifier; solubilises essential oils into aqueous phase (minor: should be 'Polysorbate 20')",flag:"ok"},{name:"PEG-40 Hydrogenated Castor Oil",note:"Non-ionic solubiliser/emulsifier for fragrance oils",flag:"ok"},{name:"Santalum Album (Sandalwood) Oil",note:"Fragrance essential oil. Known contact sensitiser; contains farnesol (EU declared allergen) and alpha-santalol. Sandalwood is IUCN Vulnerable: sourcing sustainability concern.",flag:"warn"},{name:"Cocos Nucifera (Coconut) Water",note:"Mineral electrolytes (potassium, magnesium); amino acids; skin and hair conditioning",flag:"ok"},{name:"Rosa Damascena (Rose) Flower Oil",note:"Fragrance essential oil. Contains geraniol, citronellol, farnesol, linalool, four major EU fragrance allergens in a full-body leave-on product.",flag:"warn"},{name:"Citrus Aurantium Dulcis (Orange) Peel Oil",note:"Fragrance essential oil. Contains limonene and linalool (EU allergens). Possible phototoxic compounds from peel oil; full-body application before UV exposure is a concern.",flag:"warn"},{name:"Niacinamide",note:"Anti-inflammatory and barrier support; meaningful benefit for skin application",flag:"ok"},{name:"Sodium PCA (Sodium Pyrrolidone Carboxylic Acid)",note:"Natural Moisturising Factor component; humectant for skin and hair",flag:"ok"},{name:"Allantoin",note:"Soothing and skin-conditioning",flag:"ok"},{name:"Potassium Sorbate",note:"Preservative; effective at pH below 6.5",flag:"ok"},{name:"Disodium EDTA",note:"Chelating agent for formula stability",flag:"ok"}],globalScreen:{eu_1223_2009:"Lavender Oil (linalool, linalyl acetate), Sandalwood Oil (farnesol), Rosa Damascena (geraniol, citronellol, farnesol, linalool), and Orange Peel Oil (limonene, linalool) all contain EU Annex III declared fragrance allergens that must be individually listed on the label above 0.001% in leave-on products. These allergens are not individually named. Potential labelling compliance gap.",india_cr_2020:"No Schedule S prohibited substances. Individual fragrance allergen labelling is not currently mandatory in India.",health_canada_hotlist:"No hotlist substances detected.",canada_nhpid:"Canada NHPID is relevant for Santalum Album and Rosa Damascena as regulated natural health product ingredients. Check applicable monographs if sold with therapeutic claims.",tga_australia:"No restricted or prohibited substances per TGA cosmetic standards.",us_fda_21cfr:"All ingredients comply with 21 CFR cosmetic ingredient use requirements.",korea_mfds:"No restricted substances. Fragrance allergen declaration requirements under Korean MFDS apply.",aicis_australia:"No restricted industrial chemicals.",echa_svhc:"No SVHC detected in formula.",iarc:"No IARC classified carcinogens in formula."},inciCompleteness:{status:"Full INCI on brand PDP",flags:["EU declared fragrance allergens from four essential oils are not individually named on the label","Polysorbate-20 formatting should be 'Polysorbate 20'"]},claimsCheck:[{claim:"Safe for daily full-body leave-on use",evidenceStatus:"Missing",decision:"Not publicly supported",note:"Four fragrance essential oils with cumulative EU allergen load in a daily full-body leave-on product. No patch test or sensitisation study has been published. The cumulative allergen exposure from full-body application is not communicated to consumers."},{claim:"Hair and body multi-use benefit",evidenceStatus:"Mentioned only",decision:"Needs proof",note:"The formulation is plausible as a lightweight multi-use product but no published efficacy study for hair or skin benefit exists."}],missingProof:["Published patch test or allergen sensitisation assessment for daily full-body leave-on use with four fragrance oils","Individual EU allergen declaration for linalool, linalyl acetate, geraniol, citronellol, farnesol, limonene","Phototoxic risk communication for Orange Peel Oil in morning use"],cleanSheetNote:"The simple base formula is functional. However, four fragrance essential oils in a daily full-body leave-on product create a high cumulative allergen exposure that is not communicated to consumers and has no published safety backup. The Sandalwood sourcing (IUCN Vulnerable) is an unanswered sustainability question.",pass_badges:["INCI Verified","Paraben-Free","SLS-Free"],warn_badges:["4 Fragrance Allergen Oils (Leave-on Full Body)","Sandalwood (IUCN Vulnerable, Sourcing Unclear)","Phototoxic Risk (Orange Peel Oil, Morning Use)","Rosa Damascena (4 EU Allergens, Leave-on)"],info_badges:["Niacinamide","Coconut Water","Sandalwood + Rose + Lavender + Orange"],indiaContext:"The Hair & Everywhere concept resonates with the Indian minimalist routine trend. However, India's high-fragrance-sensitisation prevalence makes the four-fragrance-oil leave-on a mismatch with its own consumer base. Traditional use of fragranced hair oils and coconut oil-based products has created a population with above-average fragrance contact reaction rates. The phototoxic compounds from Orange Peel Oil are especially concerning for morning use before going outdoors in India's UV-intense environment. For fragrance-sensitive Indian consumers with PIH or active skin conditions, this product should be avoided for skin application.",analyzedAt:"2026-06-10",concernTags:["Hair Hydration","Multi-Use"],suitabilityTags:[],cautionTags:["Contains Fragrance","Fragrance Allergen Flag","Essential Oil Flag","Phototoxic Risk"],fragranceStatus:"essential-oil",alcoholStatus:"free"},{productName:"Fuller Without Filler Lip Plumper",slug:"fuller-without-filler-lip-plumper",brand:c,brandSlug:b,priceRange:"Rs.649",productType:"leave-on",category:"Lip Care",subCategory:"Lip Treatment",concern:"Lip fullness, volume, SPF lip protection, glossy finish",summary:"A capsaicin-based lip plumper with a three-UV-filter SPF system. Capsicum Frutescens (Chilli) Fruit Extract is the plumping mechanism: capsaicin causes transient vasodilation via heat-sensitive receptor activation in the perioral vascular network, creating a temporary swelling effect. The three UV filters (Ethylhexyl Methoxycinnamate/Octinoxate, Homosalate, Octocrylene) provide lip SPF protection. Two significant concerns specific to the lip application route: (1) Lips are regularly touched and ingested; oral exposure to Octinoxate (under FDA and EU hormonal disruption review), Homosalate (FDA Category III, possible hormonal effects), and Octocrylene (degrades to benzophenone in-tube over time) is substantially higher than from skin application. (2) Capsaicin causes transient burning that intensifies with lip sensitivity or open fissures. One spelling error: Caprylic/Capric Triglyceride is listed as 'Caprylic/Capric Tryglyceride'.",score:52,scoreLabel:"Fair",publicDecisionLabel:"Needs proof",image:"https://antinorm.co/cdn/shop/files/74_597ea466-6d43-46dc-8a10-d9e2eb8714f3.png?v=1768286976",pillars:[{name:"Public INCI Safety Screen",score:18,max:30,note:"Lips represent a high oral-ingestion exposure route; ingredients applied to the lips are regularly licked, transferred to food and drink, and absorbed at substantially higher rates than ingredients on regular skin. Ethylhexyl Methoxycinnamate (Octinoxate) is under FDA and EU hormonal disruption review and is an EU-restricted leave-on filter: mandatory -6 deduction for Octinoxate in leave-on product. Homosalate is FDA Category III (insufficient safety data for OTC use); human monitoring shows blood detection within 2 hours of skin application; the oral route from lip use amplifies this substantially. Discretionary -3 for Homosalate in an oral-exposure lip product. Octocrylene degrades to benzophenone (suspected hormonal disruptor) under UV or heat in the product tube over time; the oral ingestion pathway from lip use is a meaningful concern. Discretionary -3 for Octocrylene in an oral-exposure lip product. No fragrance, no parabens. Capsaicin from Capsicum Frutescens causes a transient burning sensation; contraindicated on cracked or inflamed lips."},{name:"Formula Logic Inference",score:16,max:25,note:"The formula base (Mineral Oil with Ethylene/Propylene/Styrene and Butylene/Ethylene/Styrene Copolymers) is the standard gel system for lip glosses: glossy, non-sticky texture. Hydrogenated Polyisobutene adds further gloss and emolliency. Castor Seed Oil is the traditional lip product emollient. Jojoba and Avocado provide conditioning. Palmitoyl Tripeptide-1 is a signal peptide for collagen stimulation. The capsaicin plumping mechanism (vasodilation via heat-sensitive receptor activation) is well-evidenced and produces a visible temporary effect. Primary gap: the three UV filters are contested choices specifically for an oral-exposure lip product where higher and more bioavailable ingestion routes apply. One spelling error (Tryglyceride instead of Triglyceride)."},{name:"Public Claim Support",score:11,max:25,note:"No independent SPF test report has been published. The oral ingestion risk from three contested UV filters is not disclosed on the product page. The temporary nature of the capsaicin plumping effect (typically 30-60 minutes) and the associated burning sensation are not clearly communicated. One ingredient spelling error (Tryglyceride). The UV filter safety concern via oral ingestion is the most significant non-disclosure, given that daily lip product use represents a routine oral exposure pathway."},{name:"Test Result Transparency",score:5,max:15,evidenceGrade:"D",note:"No published SPF test report for the SPF protection claim. No clinical study for capsaicin plumping duration or efficacy. For a product making an SPF claim and a plumping efficacy claim, the complete absence of published evidence is a notable gap. Grade D reflects no published study and an elevated safety concern from the three contested UV filters in an oral-exposure application."},{name:"Consumer Clarity",score:2,max:5,note:"The oral ingestion risk from three contested UV filters is not communicated on the product page. The temporary nature of the capsaicin plumping effect and the burning sensation are not clearly disclosed. The spelling error in the ingredient list (Tryglyceride) reduces label accuracy. No SPF test certificate is published."}],keyActives:[{name:"Capsicum Frutescens Fruit Extract (Capsaicin)",function:"Transient vasodilation via heat-sensitive receptor activation in perioral blood vessels; temporary lip plumping via increased blood flow"},{name:"Palmitoyl Tripeptide-1",function:"Signal peptide; stimulates collagen I, III and fibronectin for potential long-term lip fullness support"},{name:"Ethylhexyl Methoxycinnamate + Homosalate + Octocrylene",function:"UV filter system for lip SPF protection. All three under FDA/EU regulatory review. Oral ingestion concern substantially elevated in lip application."},{name:"Ricinus Communis (Castor) Seed Oil",function:"Traditional lip gloss base; ricinoleic acid provides viscosity and gloss"}],ingredients:[{name:"Mineral Oil (And) Ethylene/Propylene/Styrene Copolymer (And) Butylene/Ethylene/Styrene Copolymer",note:"Hydrocarbon gel base system for lip gloss texture; provides gloss, structure, and non-sticky feel. All petrochemical-derived.",flag:"ok"},{name:"Hydrogenated Polyisobutene",note:"Non-volatile synthetic hydrocarbon emollient; high gloss, excellent spreading on lips",flag:"ok"},{name:"Caprylic/Capric Triglyceride",note:"MCT emollient from coconut/palm; lightweight, non-greasy. Listed as 'Tryglyceride' in the ingredient list, a spelling error.",flag:"warn"},{name:"Octyldodecanol",note:"Fatty alcohol emollient; skin-feel modifier",flag:"ok"},{name:"Ethylhexyl Methoxycinnamate",note:"Octinoxate; UVB filter. FDA Category III (insufficient safety data). Under hormonal disruptor review in EU. Significant oral ingestion concern when applied to lips daily.",flag:"warn"},{name:"Homosalate",note:"UVB filter. FDA Category III. Human monitoring shows blood detection within 2 hours of skin application. Oral route from lip application amplifies exposure substantially.",flag:"warn"},{name:"Octocrylene",note:"UVB/UVA filter. Degrades to benzophenone (suspected hormonal disruptor) over time under UV or heat. Oral ingestion from lip use is a meaningful exposure pathway.",flag:"warn"},{name:"Ozokerite",note:"Mineral wax from petroleum; provides structure/hardness to lip product",flag:"ok"},{name:"Ricinus Communis (Castor) Seed Oil",note:"Ricinoleic acid; traditional lip emollient. Provides viscosity, gloss, and adhesion",flag:"ok"},{name:"Persea Gratissima (Avocado) Oil",note:"Oleic acid-dominant emollient; skin-conditioning and vitamin-rich",flag:"ok"},{name:"Simmondsia Chinensis (Jojoba) Seed Oil",note:"Liquid wax ester; non-comedogenic, lightweight lip conditioning",flag:"ok"},{name:"Palmitoyl Tripeptide-1",note:"Signal peptide; stimulates collagen I, III, fibronectin. Innovative addition for a lip plumper.",flag:"ok"},{name:"Silica",note:"Absorbent silica particles; light-diffusing and texture modifier",flag:"ok"},{name:"Tocopheryl Acetate",note:"Vitamin E ester antioxidant; stabilises oil phase",flag:"ok"},{name:"Iridescent Gold CI 77480",note:"Gold colorant pigment for iridescent finish",flag:"ok"},{name:"Phenoxyethanol",note:"Preservative; within EU/India 1% limit",flag:"info"},{name:"Capsicum Frutescens Fruit Extract",note:"Capsaicin-containing chilli extract; heat-receptor agonist. Causes vasodilation and temporary lip plumping. Contraindicated on cracked or inflamed lips.",flag:"info"}],globalScreen:{eu_1223_2009:"Ethylhexyl Methoxycinnamate (Octinoxate) is a restricted UV filter in the EU under Annex VI with concentration limits. No banned substances. Lip product application creates a higher oral ingestion exposure route not captured in standard dermal absorption safety assessments.",india_cr_2020:"All UV filters are Schedule S permitted. No prohibited substances.",health_canada_hotlist:"Homosalate has been reviewed for potential endocrine disruption; no hotlist ban current. No other hotlist substances.",canada_nhpid:"Not applicable. No Natural Health Product claims.",tga_australia:"UV filters comply with Australian standards. No restricted substances.",us_fda_21cfr:"Homosalate and Ethylhexyl Methoxycinnamate are FDA Category III OTC sunscreen ingredients (insufficient safety data). Product sold in India, not the US.",korea_mfds:"No restricted substances under Korean MFDS cosmetics regulations.",aicis_australia:"No restricted industrial chemicals.",echa_svhc:"No SVHC detected in formula.",iarc:"No IARC classified carcinogens in formula."},inciCompleteness:{status:"Full INCI on brand PDP",flags:["Caprylic/Capric Triglyceride listed as 'Caprylic/Capric Tryglyceride' (spelling error)","No concentration disclosures for UV filters; oral ingestion risk from three contested filters not communicated"]},claimsCheck:[{claim:"SPF lip protection",evidenceStatus:"Mentioned only",decision:"Needs proof",note:"Three UV filters are present but no independent SPF test report has been published to confirm the stated protection factor."},{claim:"Lip plumping via capsaicin",evidenceStatus:"Evidence visible",decision:"Publicly supported",note:"Capsaicin-induced vasodilation via heat-sensitive receptor activation is a well-evidenced plumping mechanism. Effect is temporary (approximately 30-60 minutes) and accompanied by a burning sensation."},{claim:"Safe UV protection for lips",evidenceStatus:"Missing",decision:"Not publicly supported",note:"All three UV filters (Octinoxate, Homosalate, Octocrylene) are under regulatory review specifically due to hormonal disruption concerns. The oral ingestion route from lip product use is not addressed or disclosed. This combination represents a meaningful unaddressed safety question for a daily lip product."}],missingProof:["Independent published SPF test report","Safety assessment addressing oral ingestion route for three contested UV filters in daily lip product use","Consumer communication on temporary nature of capsaicin plumping and associated burning sensation"],cleanSheetNote:"The capsaicin plumping mechanism works and is honestly the product's strongest feature. The three contested UV filters (Octinoxate, Homosalate, Octocrylene) represent a poor choice specifically for a lip application where oral ingestion is routine and unavoidable. Replacing with Tinosorb S, DHHB, or other photostable filters with better oral safety profiles would significantly improve this scorecard.",pass_badges:["INCI Verified","Paraben-Free","Palmitoyl Tripeptide-1"],warn_badges:["Octinoxate (Hormonal Disruption Review, Lip Ingestion Route)","Homosalate (FDA Cat.III, Lip Ingestion Route)","Octocrylene (Degrades to Benzophenone)","No SPF Test Report Published"],info_badges:["Capsaicin Plumping (Temporary)","SPF Lip Protection","Iridescent Gold Finish"],indiaContext:"Lip plumpers have growing demand in the Indian market but the UV filter safety concern via lip ingestion is particularly relevant given that Indian consumers often drink hot beverages (chai, coffee) immediately after applying lip products, accelerating oral transfer. The capsaicin plumping effect is temporary (30-60 minutes) and will cause a burning sensation that increases with lips already sensitised by dry winter conditions in North India. Adequate SPF lip protection is genuinely undervalued in India. However, the three contested UV filters used here would ideally be replaced with Tinosorb S, DHHB, or other photostable options with better safety profiles for oral exposure.",analyzedAt:"2026-06-10",concernTags:["Lip Volume","Lip Protection"],suitabilityTags:["Daily Use"],cautionTags:["SPF Not Verified","Contested UV Filters","Capsaicin Burning"],fragranceStatus:"free",alcoholStatus:"free"}].reduce((a,b)=>a+b.score,0),a.s(["scoreColors",0,function(a){return a>=90?{ring:"#0d9488",bg:"bg-teal-50",text:"text-teal-700",border:"border-teal-200"}:a>=70?{ring:"#2563eb",bg:"bg-blue-50",text:"text-blue-700",border:"border-blue-200"}:a>=50?{ring:"#d97706",bg:"bg-amber-50",text:"text-amber-700",border:"border-amber-200"}:{ring:"#dc2626",bg:"bg-red-50",text:"text-red-700",border:"border-red-200"}}],1162)}];

